insert into public.import_issues(batch_id,family_id,source_row,source_reference,severity,messages,source_values) select c.batch_id,c.family_id,s.source_row,s.source_reference,s.severity,s.messages,s.source_values from src s cross join _excel_ctx c where exists(select 1 from public.import_batches b where b.id=c.batch_id) and not exists(select 1 from public.import_issues i where i.family_id=c.family_id and i.source_reference=s.source_reference);
